// The preview can't follow a real navigation, so each submit handler cancels it
// and logs the request the browser builds (SIMULATED from the rule:
// GET replaces the action's whole query with the form data; POST keeps it).
function requestFor(form, submitter) {
  const url = new URL(form.getAttribute('action'), 'https://shop.example');
  const data = new URLSearchParams(new FormData(form, submitter)).toString();
  if (form.method === 'get') return `GET ${url.pathname}?${data}`;
  return `POST ${url.pathname}${url.search}  body: ${data}`;
}

