// Simulation: no network here, so the files are Blob URLs. slow.js is padded with a
// ~30 MB comment so it really takes longer to load than fast.js.
const files = {
  'slow.js': '/*' + ' '.repeat(30e6) + '*/ console.log("  slow.js ran")',
  'fast.js': 'console.log("  fast.js ran")',
};

function run(change) {
  console.log(change || '(no change)');
  for (const src of ['slow.js', 'fast.js']) {
    const s = document.createElement('script');
    s.src = URL.createObjectURL(new Blob([files[src]], { type: 'text/javascript' }));
    if (change === 's.async = false') s.async = false;
    if (change === 's.defer = true') s.defer = true;
    if (change === "s.type = 'module'") s.type = 'module';
    document.head.append(s);
  }
}

