// Fix: a check that can tell "loaded" from "broken"
async function isUsable(src) {
  const img = new Image();
  img.src = src;
  try {
    await img.decode();
    return img.complete && img.naturalWidth > 0;
  } catch (err) {
    console.log('  decode() rejected with', err.name);
    return false;
  }
}
