function inner(useSrcset) {
  const fake = (name, w, h) => URL.createObjectURL(new Blob([`<svg xmlns="http://www.w3.org/2000/svg" ` +
    `width="${w}" height="${h}"><rect width="100%" height="100%" fill="#9c8"/>` +
    `<text x="10" y="${h / 2}" font-size="${h / 6}">${name}</text></svg>`], { type: 'image/svg+xml' }));
  const urls = { 'small.png': fake('small.png', 400, 300), 'large.png': fake('large.png', 1000, 750) };
  const name = (url) => Object.keys(urls).find((n) => urls[n] === url);
  const pic = new Image();
  pic.alt = 'Garden path';
  pic.src = urls['small.png'];
  if (useSrcset) {
    pic.srcset = `${urls['small.png']} 400w, ${urls['large.png']} 1000w`;
    pic.sizes = '100vw';
  }
  pic.onload = () => parent.postMessage({ line: `src: ${name(pic.src)}, currentSrc: ` +
    `${name(pic.currentSrc)}, naturalWidth: ${pic.naturalWidth}` }, '*');
  document.body.append(pic);
}
document.querySelectorAll('.vp').forEach((box) => {
  const w = +box.dataset.w, h = 420, scale = Math.min(1, 400 / w);
